use crate::prng::Prng;
use std::collections::{HashMap, HashSet};
use wabisabi_syntax::ast::*;
use wabisabi_syntax::parse_luau;

pub const RELEASE_HEADER: &str =
    "-- generated by wabi sabi obfuscator [https://wabisabi.mom/obfuscator]";

const LETTERS: &[u8; 52] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

fn is_luau_keyword(s: &str) -> bool {
    matches!(
        s,
        "and"
            | "break"
            | "do"
            | "else"
            | "elseif"
            | "end"
            | "false"
            | "for"
            | "function"
            | "goto"
            | "if"
            | "in"
            | "local"
            | "nil"
            | "not"
            | "or"
            | "repeat"
            | "return"
            | "then"
            | "true"
            | "until"
            | "while"
            | "continue"
            | "export"
            | "type"
            | "typeof"
    )
}

fn is_public_global(s: &str) -> bool {
    matches!(
        s,
        "bit32"
            | "table"
            | "getfenv"
            | "coroutine"
            | "string"
            | "buffer"
            | "type"
            | "debug"
            | "unpack"
            | "tonumber"
            | "select"
    )
}

fn is_public_member(s: &str) -> bool {
    matches!(
        s,
        "band"
            | "bnot"
            | "bor"
            | "bxor"
            | "byte"
            | "char"
            | "countlz"
            | "countrz"
            | "create"
            | "format"
            | "fromstring"
            | "gsub"
            | "info"
            | "lrotate"
            | "lshift"
            | "move"
            | "pack"
            | "readf32"
            | "readf64"
            | "readi16"
            | "readi32"
            | "rrotate"
            | "rshift"
            | "sub"
            | "traceback"
            | "unpack"
            | "wrap"
            | "writeu32"
            | "yield"
    )
}

fn is_public_string(bytes: &[u8]) -> bool {
    if bytes.len() <= 2 || bytes.starts_with(b"WABI") {
        return true;
    }
    matches!(
        bytes,
        b"copy"
            | b"create"
            | b"function"
            | b"number"
            | b"readstring"
            | b"readu16"
            | b"readu32"
            | b"readu8"
            | b"slf"
            | b"!!!!!"
    )
}

/// Generates unique, compact 1–2 character identifiers for authored source templates
/// before lexical AST renaming runs.
pub struct IdGen {
    counter: usize,
}

impl IdGen {
    pub fn new(_rng: &mut Prng) -> Self {
        Self { counter: 0 }
    }

    pub fn next(&mut self, _rng: &mut Prng) -> String {
        let id = self.counter;
        self.counter += 1;
        format!("__ws{id}")
    }
}

/// Builds the 1–2 char short identifier candidate sequence from a per-seed shuffled alphabet:
/// 1. Shuffled 52 single ASCII letters (`a..Z`)
/// 2. `<letter><letter>` (`aa, ab, ...` in the shuffled alphabet)
/// 3. `<letter><digit>` (`a0..Z9` overflow capacity)
fn build_short_candidates(rng: &mut Prng) -> Vec<String> {
    let mut alpha = *LETTERS;
    rng.shuffle(&mut alpha);

    let mut out = Vec::with_capacity(52 + 52 * 62);
    for &c in &alpha {
        let s = (c as char).to_string();
        if !is_luau_keyword(&s) {
            out.push(s);
        }
    }
    for &c1 in &alpha {
        for &c2 in &alpha {
            let mut s = String::with_capacity(2);
            s.push(c1 as char);
            s.push(c2 as char);
            if !is_luau_keyword(&s) {
                out.push(s);
            }
        }
    }
    for d in b'0'..=b'9' {
        for &c in &alpha {
            let mut s = String::with_capacity(2);
            s.push(c as char);
            s.push(d as char);
            if !is_luau_keyword(&s) {
                out.push(s);
            }
        }
    }
    out
}

/// Strips a raw seed word down to a valid Luau identifier fragment (ASCII alphanumerics only)
/// and requires it to begin with a letter so it can safely start an identifier.
fn sanitize_seed_word(raw: &str) -> Option<String> {
    let s: String = raw.chars().filter(|c| c.is_ascii_alphanumeric()).collect();
    if s.is_empty() || !s.as_bytes()[0].is_ascii_alphabetic() {
        return None;
    }
    Some(s)
}

/// Builds the identifier candidate sequence from a user-supplied seed word list.
///
/// Given seed words like `["waffles", "pancakes"]`, it produces a large per-seed shuffled
/// pool of valid Luau identifiers by combining single words and ordered word pairs, then
/// appending ascending numeric suffixes once the bare forms are exhausted — e.g.
/// `waffles`, `pancakeswaffles`, `waffles1`, `wafflespancakes1`, `pancakeswaffles12`.
///
/// Returns an empty vec if no usable words are supplied (caller falls back to short names).
fn build_wordlist_candidates(words: &[String], rng: &mut Prng) -> Vec<String> {
    let mut clean: Vec<String> = Vec::new();
    let mut seen = HashSet::new();
    for w in words {
        if let Some(s) = sanitize_seed_word(w) {
            if seen.insert(s.clone()) {
                clean.push(s);
            }
        }
    }
    if clean.is_empty() {
        return Vec::new();
    }

    // Base forms: every single word plus every ordered 2-word concatenation.
    let mut bases: Vec<String> = Vec::new();
    let mut base_seen: HashSet<String> = HashSet::new();
    for w in &clean {
        if base_seen.insert(w.clone()) {
            bases.push(w.clone());
        }
    }
    for a in &clean {
        for b in &clean {
            let p = format!("{a}{b}");
            if base_seen.insert(p.clone()) {
                bases.push(p);
            }
        }
    }
    rng.shuffle(&mut bases);

    // Large pool so neither the local renamer nor the member renamer can exhaust it.
    const TARGET: usize = 20_000;
    let mut out: Vec<String> = Vec::with_capacity(TARGET);
    let mut out_seen: HashSet<String> = HashSet::new();

    // Bare word forms first (no numeric suffix).
    for b in &bases {
        if !is_luau_keyword(b) && out_seen.insert(b.clone()) {
            out.push(b.clone());
        }
    }
    // Then ascending numeric suffixes applied to each base form.
    let mut suffix: u32 = 1;
    while out.len() < TARGET {
        for b in &bases {
            let cand = format!("{b}{suffix}");
            if out_seen.insert(cand.clone()) {
                out.push(cand);
                if out.len() >= TARGET {
                    break;
                }
            }
        }
        suffix = suffix.saturating_add(1);
        if suffix > 2_000_000 {
            break; // safety valve; unreachable for any non-empty word list
        }
    }
    out
}

/// Picks the identifier candidate pool for this build: user seed words when supplied
/// (and usable), otherwise the default shuffled 1–2 char short-name scheme.
fn build_candidates(names: Option<&[String]>, rng: &mut Prng) -> Vec<String> {
    if let Some(words) = names {
        let c = build_wordlist_candidates(words, rng);
        if !c.is_empty() {
            return c;
        }
    }
    build_short_candidates(rng)
}

fn collect_unbound_globals(root: &Block) -> HashSet<String> {
    struct Collector {
        scopes: Vec<HashSet<String>>,
        globals: HashSet<String>,
    }

    impl Collector {
        fn is_bound(&self, name: &str) -> bool {
            self.scopes.iter().rev().any(|s| s.contains(name))
        }

        fn bind(&mut self, name: &str) {
            if let Some(top) = self.scopes.last_mut() {
                top.insert(name.to_string());
            }
        }

        fn visit_block(&mut self, b: &Block) {
            self.scopes.push(HashSet::new());
            for stmt in &b.stmts {
                self.visit_stmt(stmt);
            }
            if let Some(rets) = &b.ret {
                for e in rets {
                    self.visit_expr(e);
                }
            }
            self.scopes.pop();
        }

        fn visit_func(&mut self, f: &FuncBody) {
            self.scopes.push(HashSet::new());
            for p in &f.params {
                self.bind(p);
            }
            self.visit_block(&f.body);
            self.scopes.pop();
        }

        fn visit_stmt(&mut self, s: &Stmt) {
            match s {
                Stmt::LocalAssign { names, values } => {
                    for v in values {
                        self.visit_expr(v);
                    }
                    for n in names {
                        self.bind(n);
                    }
                }
                Stmt::LocalFunction { name, func } => {
                    self.bind(name);
                    self.visit_func(func);
                }
                Stmt::FunctionDef { name, func } => {
                    if !self.is_bound(&name.base) {
                        self.globals.insert(name.base.clone());
                    }
                    self.visit_func(func);
                }
                Stmt::Assign { targets, values } => {
                    for t in targets {
                        self.visit_lvalue(t);
                    }
                    for v in values {
                        self.visit_expr(v);
                    }
                }
                Stmt::CompoundAssign { target, value, .. } => {
                    self.visit_lvalue(target);
                    self.visit_expr(value);
                }
                Stmt::Call(e) => self.visit_expr(e),
                Stmt::Do(b) => self.visit_block(b),
                Stmt::While { cond, body } => {
                    self.visit_expr(cond);
                    self.visit_block(body);
                }
                Stmt::Repeat { body, cond } => {
                    self.scopes.push(HashSet::new());
                    for st in &body.stmts {
                        self.visit_stmt(st);
                    }
                    if let Some(rets) = &body.ret {
                        for e in rets {
                            self.visit_expr(e);
                        }
                    }
                    self.visit_expr(cond);
                    self.scopes.pop();
                }
                Stmt::If {
                    branches,
                    else_branch,
                } => {
                    for (c, b) in branches {
                        self.visit_expr(c);
                        self.visit_block(b);
                    }
                    if let Some(eb) = else_branch {
                        self.visit_block(eb);
                    }
                }
                Stmt::ForNum {
                    var,
                    start,
                    limit,
                    step,
                    body,
                } => {
                    self.visit_expr(start);
                    self.visit_expr(limit);
                    if let Some(st) = step {
                        self.visit_expr(st);
                    }
                    self.scopes.push(HashSet::new());
                    self.bind(var);
                    self.visit_block(body);
                    self.scopes.pop();
                }
                Stmt::ForIn {
                    vars,
                    iter_exprs,
                    body,
                } => {
                    for ie in iter_exprs {
                        self.visit_expr(ie);
                    }
                    self.scopes.push(HashSet::new());
                    for v in vars {
                        self.bind(v);
                    }
                    self.visit_block(body);
                    self.scopes.pop();
                }
                Stmt::Break | Stmt::Continue => {}
            }
        }

        fn visit_lvalue(&mut self, lv: &LValue) {
            match lv {
                LValue::Name(n) => {
                    if !self.is_bound(n) {
                        self.globals.insert(n.clone());
                    }
                }
                LValue::Index { table, key } => {
                    self.visit_expr(table);
                    self.visit_expr(key);
                }
                LValue::Field { table, .. } => {
                    self.visit_expr(table);
                }
            }
        }

        fn visit_expr(&mut self, e: &Expr) {
            match e {
                Expr::Nil | Expr::Bool(_) | Expr::Number(_) | Expr::String(_) | Expr::Vararg => {}
                Expr::Name(n) => {
                    if !self.is_bound(n) {
                        self.globals.insert(n.clone());
                    }
                }
                Expr::Table(fields) => {
                    for f in fields {
                        match f {
                            TableField::Index { key, value } => {
                                self.visit_expr(key);
                                self.visit_expr(value);
                            }
                            TableField::Name { value, .. } | TableField::Array(value) => {
                                self.visit_expr(value);
                            }
                        }
                    }
                }
                Expr::Function(func) => self.visit_func(func),
                Expr::IfExpr {
                    branches,
                    else_expr,
                } => {
                    for (c, v) in branches {
                        self.visit_expr(c);
                        self.visit_expr(v);
                    }
                    self.visit_expr(else_expr);
                }
                Expr::InterpString { exprs, .. } => {
                    for ex in exprs {
                        self.visit_expr(ex);
                    }
                }
                Expr::Index { table, key } => {
                    self.visit_expr(table);
                    self.visit_expr(key);
                }
                Expr::Field { table, .. } => self.visit_expr(table),
                Expr::Call { func, args } => {
                    self.visit_expr(func);
                    for a in args {
                        self.visit_expr(a);
                    }
                }
                Expr::MethodCall { receiver, args, .. } => {
                    self.visit_expr(receiver);
                    for a in args {
                        self.visit_expr(a);
                    }
                }
                Expr::Unary { expr, .. } | Expr::Paren(expr) => self.visit_expr(expr),
                Expr::Binary { lhs, rhs, .. } => {
                    self.visit_expr(lhs);
                    self.visit_expr(rhs);
                }
            }
        }
    }

    let mut c = Collector {
        scopes: Vec::new(),
        globals: HashSet::new(),
    };
    c.visit_block(root);
    c.globals
}

/// Counts total local declarations inside a `Block` (excluding nested `FuncBody`s) so parent
/// functions pre-allocate their own short names before assigning child closures (`styling.py`).
fn count_direct_fn_locals_in_block(b: &Block) -> usize {
    let mut total = 0;
    for s in &b.stmts {
        total += match s {
            Stmt::LocalAssign { names, .. } => names.len(),
            Stmt::LocalFunction { .. } => 1,
            Stmt::Do(inner)
            | Stmt::While { body: inner, .. }
            | Stmt::Repeat { body: inner, .. } => count_direct_fn_locals_in_block(inner),
            Stmt::If {
                branches,
                else_branch,
            } => {
                branches
                    .iter()
                    .map(|(_, blk)| count_direct_fn_locals_in_block(blk))
                    .sum::<usize>()
                    + else_branch
                        .as_ref()
                        .map(count_direct_fn_locals_in_block)
                        .unwrap_or(0)
            }
            Stmt::ForNum { body, .. } => 1 + count_direct_fn_locals_in_block(body),
            Stmt::ForIn { vars, body, .. } => vars.len() + count_direct_fn_locals_in_block(body),
            _ => 0,
        };
    }
    total
}

struct ScopeRenamer {
    candidates: Vec<String>,
    globals: HashSet<String>,
    env: Vec<HashMap<String, String>>,
}

struct FnPool {
    names: Vec<String>,
    cursor: usize,
    all_reserved_for_children: HashSet<String>,
}

impl ScopeRenamer {
    fn make_fn_pool(&self, inherited: &HashSet<String>, count: usize) -> FnPool {
        let mut names = Vec::with_capacity(count);
        let mut all_res = inherited.clone();
        for cand in &self.candidates {
            if names.len() >= count {
                break;
            }
            if !inherited.contains(cand) && !self.globals.contains(cand) {
                names.push(cand.clone());
                all_res.insert(cand.clone());
            }
        }
        assert_eq!(
            names.len(),
            count,
            "exhausted 1-2 char short local bindings ({count} needed)"
        );
        FnPool {
            names,
            cursor: 0,
            all_reserved_for_children: all_res,
        }
    }

    fn alloc_local(&mut self, old: &str, pool: &mut FnPool) -> String {
        let new_name = pool.names[pool.cursor].clone();
        pool.cursor += 1;
        self.env
            .last_mut()
            .expect("active lexical frame")
            .insert(old.to_string(), new_name.clone());
        new_name
    }

    fn resolve(&self, name: &str) -> String {
        for frame in self.env.iter().rev() {
            if let Some(mapped) = frame.get(name) {
                return mapped.clone();
            }
        }
        name.to_string()
    }

    fn rename_root(&mut self, root: &mut Block) {
        let count = count_direct_fn_locals_in_block(root);
        let empty = HashSet::new();
        let mut pool = self.make_fn_pool(&empty, count);
        self.rename_block(root, &mut pool);
    }

    fn rename_func(&mut self, func: &mut FuncBody, inherited: &HashSet<String>) {
        let count = func.params.len() + count_direct_fn_locals_in_block(&func.body);
        let mut pool = self.make_fn_pool(inherited, count);
        self.env.push(HashMap::new());
        for p in &mut func.params {
            *p = self.alloc_local(p, &mut pool);
        }
        self.rename_block(&mut func.body, &mut pool);
        self.env.pop();
    }

    fn rename_block(&mut self, b: &mut Block, pool: &mut FnPool) {
        self.env.push(HashMap::new());
        for stmt in &mut b.stmts {
            self.rename_stmt(stmt, pool);
        }
        if let Some(rets) = &mut b.ret {
            for e in rets {
                self.rename_expr(e, pool);
            }
        }
        self.env.pop();
    }

    fn rename_stmt(&mut self, s: &mut Stmt, pool: &mut FnPool) {
        match s {
            Stmt::LocalAssign { names, values } => {
                for v in values {
                    self.rename_expr(v, pool);
                }
                for n in names {
                    *n = self.alloc_local(n, pool);
                }
            }
            Stmt::LocalFunction { name, func } => {
                *name = self.alloc_local(name, pool);
                let inherited = pool.all_reserved_for_children.clone();
                self.rename_func(func, &inherited);
            }
            Stmt::FunctionDef { name, func } => {
                name.base = self.resolve(&name.base);
                let inherited = pool.all_reserved_for_children.clone();
                self.rename_func(func, &inherited);
            }
            Stmt::Assign { targets, values } => {
                for t in targets {
                    self.rename_lvalue(t, pool);
                }
                for v in values {
                    self.rename_expr(v, pool);
                }
            }
            Stmt::CompoundAssign { target, value, .. } => {
                self.rename_lvalue(target, pool);
                self.rename_expr(value, pool);
            }
            Stmt::Call(e) => self.rename_expr(e, pool),
            Stmt::Do(b) => self.rename_block(b, pool),
            Stmt::While { cond, body } => {
                self.rename_expr(cond, pool);
                self.rename_block(body, pool);
            }
            Stmt::Repeat { body, cond } => {
                self.env.push(HashMap::new());
                for st in &mut body.stmts {
                    self.rename_stmt(st, pool);
                }
                if let Some(rets) = &mut body.ret {
                    for e in rets {
                        self.rename_expr(e, pool);
                    }
                }
                self.rename_expr(cond, pool);
                self.env.pop();
            }
            Stmt::If {
                branches,
                else_branch,
            } => {
                for (c, b) in branches {
                    self.rename_expr(c, pool);
                    self.rename_block(b, pool);
                }
                if let Some(eb) = else_branch {
                    self.rename_block(eb, pool);
                }
            }
            Stmt::ForNum {
                var,
                start,
                limit,
                step,
                body,
            } => {
                self.rename_expr(start, pool);
                self.rename_expr(limit, pool);
                if let Some(st) = step {
                    self.rename_expr(st, pool);
                }
                self.env.push(HashMap::new());
                *var = self.alloc_local(var, pool);
                self.rename_block(body, pool);
                self.env.pop();
            }
            Stmt::ForIn {
                vars,
                iter_exprs,
                body,
            } => {
                for ie in iter_exprs {
                    self.rename_expr(ie, pool);
                }
                self.env.push(HashMap::new());
                for v in vars {
                    *v = self.alloc_local(v, pool);
                }
                self.rename_block(body, pool);
                self.env.pop();
            }
            Stmt::Break | Stmt::Continue => {}
        }
    }

    fn rename_lvalue(&mut self, lv: &mut LValue, pool: &mut FnPool) {
        match lv {
            LValue::Name(n) => *n = self.resolve(n),
            LValue::Index { table, key } => {
                self.rename_expr(table, pool);
                self.rename_expr(key, pool);
            }
            LValue::Field { table, .. } => self.rename_expr(table, pool),
        }
    }

    fn rename_expr(&mut self, e: &mut Expr, pool: &mut FnPool) {
        match e {
            Expr::Nil | Expr::Bool(_) | Expr::Number(_) | Expr::String(_) | Expr::Vararg => {}
            Expr::Name(n) => *n = self.resolve(n),
            Expr::Table(fields) => {
                for f in fields {
                    match f {
                        TableField::Index { key, value } => {
                            self.rename_expr(key, pool);
                            self.rename_expr(value, pool);
                        }
                        TableField::Name { value, .. } | TableField::Array(value) => {
                            self.rename_expr(value, pool);
                        }
                    }
                }
            }
            Expr::Function(func) => {
                let inherited = pool.all_reserved_for_children.clone();
                self.rename_func(func, &inherited);
            }
            Expr::IfExpr {
                branches,
                else_expr,
            } => {
                for (c, v) in branches {
                    self.rename_expr(c, pool);
                    self.rename_expr(v, pool);
                }
                self.rename_expr(else_expr, pool);
            }
            Expr::InterpString { exprs, .. } => {
                for ex in exprs {
                    self.rename_expr(ex, pool);
                }
            }
            Expr::Index { table, key } => {
                self.rename_expr(table, pool);
                self.rename_expr(key, pool);
            }
            Expr::Field { table, .. } => self.rename_expr(table, pool),
            Expr::Call { func, args } => {
                self.rename_expr(func, pool);
                for a in args {
                    self.rename_expr(a, pool);
                }
            }
            Expr::MethodCall { receiver, args, .. } => {
                self.rename_expr(receiver, pool);
                for a in args {
                    self.rename_expr(a, pool);
                }
            }
            Expr::Unary { expr, .. } | Expr::Paren(expr) => self.rename_expr(expr, pool),
            Expr::Binary { lhs, rhs, .. } => {
                self.rename_expr(lhs, pool);
                self.rename_expr(rhs, pool);
            }
        }
    }
}

/// Renames authored non-public table fields and method names (such as the outer carrier
/// `carrierEntry` and `carrierBlob`) across the parsed AST into 1–2 char names (`a..Z`, `aa..ZZ`).
struct MemberRenamer {
    candidates: Vec<String>,
    cursor: usize,
    reserved: HashSet<String>,
    map: HashMap<String, String>,
}

impl MemberRenamer {
    fn new(candidates: Vec<String>, rng: &mut Prng) -> Self {
        let mut reserved = HashSet::new();
        reserved.insert("n".to_string()); // `table.pack(...).n`
        let cursor = rng.next_usize(96.min(candidates.len().max(1)));
        Self {
            candidates,
            cursor,
            reserved,
            map: HashMap::new(),
        }
    }

    fn map_member(&mut self, m: &mut String) {
        if m.len() <= 2 || is_public_member(m) {
            return;
        }
        if let Some(existing) = self.map.get(m) {
            *m = existing.clone();
            return;
        }
        while self.cursor < self.candidates.len() {
            let cand = &self.candidates[self.cursor];
            self.cursor += 1;
            if !self.reserved.contains(cand) {
                let assigned = cand.clone();
                self.reserved.insert(assigned.clone());
                self.map.insert(m.clone(), assigned.clone());
                *m = assigned;
                return;
            }
        }
        panic!("exhausted 1-2 char short member bindings");
    }

    fn rename_block(&mut self, b: &mut Block) {
        for s in &mut b.stmts {
            self.rename_stmt(s);
        }
        if let Some(rets) = &mut b.ret {
            for e in rets {
                self.rename_expr(e);
            }
        }
    }

    fn rename_stmt(&mut self, s: &mut Stmt) {
        match s {
            Stmt::LocalAssign { values, .. } => {
                for v in values {
                    self.rename_expr(v);
                }
            }
            Stmt::LocalFunction { func, .. } => self.rename_block(&mut func.body),
            Stmt::FunctionDef { name, func } => {
                for f in &mut name.fields {
                    self.map_member(f);
                }
                if let Some(m) = &mut name.method {
                    self.map_member(m);
                }
                self.rename_block(&mut func.body);
            }
            Stmt::Assign { targets, values } => {
                for t in targets {
                    match t {
                        LValue::Name(_) => {}
                        LValue::Index { table, key } => {
                            self.rename_expr(table);
                            self.rename_expr(key);
                        }
                        LValue::Field { table, field } => {
                            self.map_member(field);
                            self.rename_expr(table);
                        }
                    }
                }
                for v in values {
                    self.rename_expr(v);
                }
            }
            Stmt::CompoundAssign { target, value, .. } => {
                match target {
                    LValue::Name(_) => {}
                    LValue::Index { table, key } => {
                        self.rename_expr(table);
                        self.rename_expr(key);
                    }
                    LValue::Field { table, field } => {
                        self.map_member(field);
                        self.rename_expr(table);
                    }
                }
                self.rename_expr(value);
            }
            Stmt::Call(e) => self.rename_expr(e),
            Stmt::Do(b) => self.rename_block(b),
            Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
                self.rename_expr(cond);
                self.rename_block(body);
            }
            Stmt::If {
                branches,
                else_branch,
            } => {
                for (c, b) in branches {
                    self.rename_expr(c);
                    self.rename_block(b);
                }
                if let Some(eb) = else_branch {
                    self.rename_block(eb);
                }
            }
            Stmt::ForNum {
                start,
                limit,
                step,
                body,
                ..
            } => {
                self.rename_expr(start);
                self.rename_expr(limit);
                if let Some(st) = step {
                    self.rename_expr(st);
                }
                self.rename_block(body);
            }
            Stmt::ForIn {
                iter_exprs, body, ..
            } => {
                for ie in iter_exprs {
                    self.rename_expr(ie);
                }
                self.rename_block(body);
            }
            Stmt::Break | Stmt::Continue => {}
        }
    }

    fn rename_expr(&mut self, e: &mut Expr) {
        match e {
            Expr::Nil | Expr::Bool(_) | Expr::Number(_) | Expr::String(_) | Expr::Vararg | Expr::Name(_) => {}
            Expr::Table(fields) => {
                for f in fields {
                    match f {
                        TableField::Index { key, value } => {
                            self.rename_expr(key);
                            self.rename_expr(value);
                        }
                        TableField::Name { field, value } => {
                            self.map_member(field);
                            self.rename_expr(value);
                        }
                        TableField::Array(value) => self.rename_expr(value),
                    }
                }
            }
            Expr::Function(f) => self.rename_block(&mut f.body),
            Expr::IfExpr {
                branches,
                else_expr,
            } => {
                for (c, v) in branches {
                    self.rename_expr(c);
                    self.rename_expr(v);
                }
                self.rename_expr(else_expr);
            }
            Expr::InterpString { exprs, .. } => {
                for ex in exprs {
                    self.rename_expr(ex);
                }
            }
            Expr::Index { table, key } => {
                self.rename_expr(table);
                self.rename_expr(key);
            }
            Expr::Field { table, field } => {
                self.map_member(field);
                self.rename_expr(table);
            }
            Expr::Call { func, args } => {
                self.rename_expr(func);
                for a in args {
                    self.rename_expr(a);
                }
            }
            Expr::MethodCall {
                receiver,
                method,
                args,
            } => {
                self.map_member(method);
                self.rename_expr(receiver);
                for a in args {
                    self.rename_expr(a);
                }
            }
            Expr::Unary { expr, .. } | Expr::Paren(expr) => self.rename_expr(expr),
            Expr::Binary { lhs, rhs, .. } => {
                self.rename_expr(lhs);
                self.rename_expr(rhs);
            }
        }
    }
}

thread_local! {
    /// Long identifiers (>2 chars) that the renamer deliberately assigned this build —
    /// populated when a user seed word list is in use. Any long name NOT in this set is a
    /// genuine leak of an original private identifier.
    static ALLOWED_LONG_NAMES: std::cell::RefCell<HashSet<String>> =
        std::cell::RefCell::new(HashSet::new());
}

fn long_name_is_allowed(n: &str) -> bool {
    ALLOWED_LONG_NAMES.with(|a| a.borrow().contains(n))
}

/// Verifies at emit time that the renamed native shell AST passes `verify_release.py`'s
/// `check_compact_names` invariants with zero private name, global, or string leaks.
///
/// `allowed_long` holds identifiers the renamer intentionally produced that exceed 2 chars
/// (from a user seed word list); every other long name is treated as a leak.
fn audit_release_ast(root: &Block, globals: &HashSet<String>, allowed_long: &HashSet<String>) {
    ALLOWED_LONG_NAMES.with(|a| *a.borrow_mut() = allowed_long.clone());

    for g in globals {
        assert!(
            is_public_global(g),
            "release audit failed: leaked non-public global `{g}` in native shell"
        );
    }

    fn walk_block(b: &Block) {
        for s in &b.stmts {
            walk_stmt(s);
        }
        if let Some(rets) = &b.ret {
            for e in rets {
                walk_expr(e);
            }
        }
    }

    fn check_local(n: &str) {
        assert!(
            n.len() <= 2 || long_name_is_allowed(n),
            "release audit failed: local binding `{n}` exceeds 2 chars"
        );
    }

    fn check_member(m: &str) {
        if m.len() > 2 && !is_public_member(m) {
            assert!(
                long_name_is_allowed(m),
                "release audit failed: private member/record field `{m}` leaked"
            );
        }
    }

    fn walk_func(f: &FuncBody) {
        for p in &f.params {
            check_local(p);
        }
        walk_block(&f.body);
    }

    fn walk_stmt(s: &Stmt) {
        match s {
            Stmt::LocalAssign { names, values } => {
                for n in names {
                    check_local(n);
                }
                for v in values {
                    walk_expr(v);
                }
            }
            Stmt::LocalFunction { name, func } => {
                check_local(name);
                walk_func(func);
            }
            Stmt::FunctionDef { name, func } => {
                for f in &name.fields {
                    check_member(f);
                }
                if let Some(m) = &name.method {
                    check_member(m);
                }
                walk_func(func);
            }
            Stmt::Assign { targets, values } => {
                for t in targets {
                    match t {
                        LValue::Name(_) => {}
                        LValue::Index { table, key } => {
                            walk_expr(table);
                            walk_expr(key);
                        }
                        LValue::Field { table, field } => {
                            check_member(field);
                            walk_expr(table);
                        }
                    }
                }
                for v in values {
                    walk_expr(v);
                }
            }
            Stmt::CompoundAssign { target, value, .. } => {
                match target {
                    LValue::Name(_) => {}
                    LValue::Index { table, key } => {
                        walk_expr(table);
                        walk_expr(key);
                    }
                    LValue::Field { table, field } => {
                        check_member(field);
                        walk_expr(table);
                    }
                }
                walk_expr(value);
            }
            Stmt::Call(e) => walk_expr(e),
            Stmt::Do(b) => walk_block(b),
            Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
                walk_expr(cond);
                walk_block(body);
            }
            Stmt::If {
                branches,
                else_branch,
            } => {
                for (c, b) in branches {
                    walk_expr(c);
                    walk_block(b);
                }
                if let Some(eb) = else_branch {
                    walk_block(eb);
                }
            }
            Stmt::ForNum {
                var,
                start,
                limit,
                step,
                body,
            } => {
                check_local(var);
                walk_expr(start);
                walk_expr(limit);
                if let Some(st) = step {
                    walk_expr(st);
                }
                walk_block(body);
            }
            Stmt::ForIn {
                vars,
                iter_exprs,
                body,
            } => {
                for v in vars {
                    check_local(v);
                }
                for ie in iter_exprs {
                    walk_expr(ie);
                }
                walk_block(body);
            }
            Stmt::Break | Stmt::Continue => {}
        }
    }

    fn walk_expr(e: &Expr) {
        match e {
            Expr::Nil | Expr::Bool(_) | Expr::Number(_) | Expr::Vararg | Expr::Name(_) => {}
            Expr::String(bytes) => {
                assert!(
                    is_public_string(bytes),
                    "release audit failed: leaked non-public string constant `{}`",
                    String::from_utf8_lossy(bytes)
                );
            }
            Expr::Table(fields) => {
                for f in fields {
                    match f {
                        TableField::Index { key, value } => {
                            walk_expr(key);
                            walk_expr(value);
                        }
                        TableField::Name { field, value } => {
                            check_member(field);
                            walk_expr(value);
                        }
                        TableField::Array(value) => walk_expr(value),
                    }
                }
            }
            Expr::Function(f) => walk_func(f),
            Expr::IfExpr {
                branches,
                else_expr,
            } => {
                for (c, v) in branches {
                    walk_expr(c);
                    walk_expr(v);
                }
                walk_expr(else_expr);
            }
            Expr::InterpString { exprs, .. } => {
                for ex in exprs {
                    walk_expr(ex);
                }
            }
            Expr::Index { table, key } => {
                walk_expr(table);
                walk_expr(key);
            }
            Expr::Field { table, field } => {
                check_member(field);
                walk_expr(table);
            }
            Expr::Call { func, args } => {
                walk_expr(func);
                for a in args {
                    walk_expr(a);
                }
            }
            Expr::MethodCall {
                receiver,
                method,
                args,
            } => {
                check_member(method);
                walk_expr(receiver);
                for a in args {
                    walk_expr(a);
                }
            }
            Expr::Unary { expr, .. } | Expr::Paren(expr) => walk_expr(expr),
            Expr::Binary { lhs, rhs, .. } => {
                walk_expr(lhs);
                walk_expr(rhs);
            }
        }
    }

    walk_block(root);

    ALLOWED_LONG_NAMES.with(|a| a.borrow_mut().clear());
}

struct MoonveilEmitter<'a> {
    tokens: Vec<String>,
    rng: &'a mut Prng,
}

impl<'a> MoonveilEmitter<'a> {
    fn push(&mut self, t: impl Into<String>) {
        self.tokens.push(t.into());
    }

    fn moonveil_int(&mut self, u: u64) -> String {
        if u < 2 {
            return u.to_string();
        }
        let mode = self.rng.next_usize(100);
        if mode < 55 {
            format!("0x{u:x}")
        } else if mode < 90 {
            format!("0b{u:b}")
        } else {
            u.to_string()
        }
    }

    fn format_number(&mut self, mut n: f64) {
        if n == 0.0 && n.is_sign_negative() {
            self.push("-");
            self.push("0.0");
            return;
        }
        if n < 0.0 {
            self.push("-");
            n = -n;
        }
        if n.is_finite() && n.fract() == 0.0 && n <= 9_007_199_254_740_992.0 {
            let tok = self.moonveil_int(n as u64);
            self.push(tok);
        } else {
            self.push(format!("{n}"));
        }
    }

    fn format_string_literal(&mut self, bytes: &[u8]) {
        let mut s = String::with_capacity(bytes.len() + 4);
        s.push('"');
        for &b in bytes {
            match b {
                b'"' => s.push_str("\\\""),
                b'\\' => s.push_str("\\\\"),
                b'\n' => s.push_str("\\n"),
                b'\r' => s.push_str("\\r"),
                b'\t' => s.push_str("\\t"),
                32..=126 => s.push(b as char),
                _ => s.push_str(&format!("\\{b:03}")),
            }
        }
        s.push('"');
        self.push(s);
    }

    fn expr_starts_with_paren(e: &Expr) -> bool {
        match e {
            Expr::Paren(_) => true,
            Expr::Index { table, .. }
            | Expr::Field { table, .. }
            | Expr::Call { func: table, .. }
            | Expr::MethodCall {
                receiver: table, ..
            } => {
                if !Self::is_prefix_expr(table) {
                    true
                } else {
                    Self::expr_starts_with_paren(table)
                }
            }
            _ => false,
        }
    }

    fn lvalue_starts_with_paren(lv: &LValue) -> bool {
        match lv {
            LValue::Name(_) => false,
            LValue::Index { table, .. } | LValue::Field { table, .. } => {
                if !Self::is_prefix_expr(table) {
                    true
                } else {
                    Self::expr_starts_with_paren(table)
                }
            }
        }
    }

    fn stmt_starts_with_paren(s: &Stmt) -> bool {
        match s {
            Stmt::Call(e) => Self::expr_starts_with_paren(e),
            Stmt::Assign { targets, .. } => targets
                .first()
                .map(Self::lvalue_starts_with_paren)
                .unwrap_or(false),
            Stmt::CompoundAssign { target, .. } => Self::lvalue_starts_with_paren(target),
            _ => false,
        }
    }

    fn is_prefix_expr(e: &Expr) -> bool {
        matches!(
            e,
            Expr::Name(_)
                | Expr::Paren(_)
                | Expr::Index { .. }
                | Expr::Field { .. }
                | Expr::Call { .. }
                | Expr::MethodCall { .. }
        )
    }

    fn bin_prec(op: BinOp) -> (u8, bool) {
        // returns `(precedence, right_associative)`
        match op {
            BinOp::Or => (1, false),
            BinOp::And => (2, false),
            BinOp::Lt | BinOp::Gt | BinOp::Le | BinOp::Ge | BinOp::Ne | BinOp::Eq => (3, false),
            BinOp::Concat => (4, true),
            BinOp::Add | BinOp::Sub => (5, false),
            BinOp::Mul | BinOp::Div | BinOp::FloorDiv | BinOp::Mod => (6, false),
            BinOp::Pow => (8, true),
        }
    }

    fn expr_prec(e: &Expr) -> u8 {
        match e {
            Expr::Binary { op, .. } => Self::bin_prec(*op).0,
            Expr::Unary { .. } => 7,
            Expr::IfExpr { .. } => 0,
            Expr::Number(n) if *n < 0.0 || (*n == 0.0 && n.is_sign_negative()) => 7,
            _ => 9,
        }
    }

    fn emit_block(&mut self, b: &Block) {
        for (idx, stmt) in b.stmts.iter().enumerate() {
            if idx > 0 && Self::stmt_starts_with_paren(stmt) {
                let prev = self.tokens.last().map(|s| s.as_str()).unwrap_or("");
                if prev != ";" {
                    self.push(";");
                }
            }
            self.emit_stmt(stmt);
        }
        if let Some(rets) = &b.ret {
            self.push("return");
            self.emit_expr_list(rets);
        }
    }

    fn emit_func_body(&mut self, f: &FuncBody) {
        self.push("(");
        for (i, p) in f.params.iter().enumerate() {
            if i > 0 {
                self.push(",");
            }
            self.push(p.clone());
        }
        if f.is_vararg {
            if !f.params.is_empty() {
                self.push(",");
            }
            self.push("...");
        }
        self.push(")");
        self.emit_block(&f.body);
        self.push("end");
    }

    fn emit_stmt(&mut self, s: &Stmt) {
        match s {
            Stmt::LocalAssign { names, values } => {
                self.push("local");
                for (i, n) in names.iter().enumerate() {
                    if i > 0 {
                        self.push(",");
                    }
                    self.push(n.clone());
                }
                if !values.is_empty() {
                    self.push("=");
                    self.emit_expr_list(values);
                }
            }
            Stmt::LocalFunction { name, func } => {
                self.push("local");
                self.push("function");
                self.push(name.clone());
                self.emit_func_body(func);
            }
            Stmt::FunctionDef { name, func } => {
                self.push("function");
                self.push(name.base.clone());
                for fld in &name.fields {
                    self.push(".");
                    self.push(fld.clone());
                }
                if let Some(m) = &name.method {
                    self.push(":");
                    self.push(m.clone());
                }
                self.emit_func_body(func);
            }
            Stmt::Assign { targets, values } => {
                for (i, t) in targets.iter().enumerate() {
                    if i > 0 {
                        self.push(",");
                    }
                    self.emit_lvalue(t);
                }
                self.push("=");
                self.emit_expr_list(values);
            }
            Stmt::CompoundAssign { target, op, value } => {
                self.emit_lvalue(target);
                let cop = match op {
                    CompoundOp::Add => "+=",
                    CompoundOp::Sub => "-=",
                    CompoundOp::Mul => "*=",
                    CompoundOp::Div => "/=",
                    CompoundOp::FloorDiv => "//=",
                    CompoundOp::Mod => "%=",
                    CompoundOp::Pow => "^=",
                    CompoundOp::Concat => "..=",
                };
                self.push(cop);
                self.emit_expr(value);
            }
            Stmt::Call(e) => self.emit_expr(e),
            Stmt::Do(b) => {
                self.push("do");
                self.emit_block(b);
                self.push("end");
            }
            Stmt::While { cond, body } => {
                self.push("while");
                self.emit_expr(cond);
                self.push("do");
                self.emit_block(body);
                self.push("end");
            }
            Stmt::Repeat { body, cond } => {
                self.push("repeat");
                self.emit_block(body);
                self.push("until");
                self.emit_expr(cond);
            }
            Stmt::If {
                branches,
                else_branch,
            } => {
                for (i, (c, b)) in branches.iter().enumerate() {
                    self.push(if i == 0 { "if" } else { "elseif" });
                    self.emit_expr(c);
                    self.push("then");
                    self.emit_block(b);
                }
                if let Some(eb) = else_branch {
                    self.push("else");
                    self.emit_block(eb);
                }
                self.push("end");
            }
            Stmt::ForNum {
                var,
                start,
                limit,
                step,
                body,
            } => {
                self.push("for");
                self.push(var.clone());
                self.push("=");
                self.emit_expr(start);
                self.push(",");
                self.emit_expr(limit);
                if let Some(st) = step {
                    self.push(",");
                    self.emit_expr(st);
                }
                self.push("do");
                self.emit_block(body);
                self.push("end");
            }
            Stmt::ForIn {
                vars,
                iter_exprs,
                body,
            } => {
                self.push("for");
                for (i, v) in vars.iter().enumerate() {
                    if i > 0 {
                        self.push(",");
                    }
                    self.push(v.clone());
                }
                self.push("in");
                self.emit_expr_list(iter_exprs);
                self.push("do");
                self.emit_block(body);
                self.push("end");
            }
            Stmt::Break => self.push("break"),
            Stmt::Continue => self.push("continue"),
        }
    }

    fn emit_lvalue(&mut self, lv: &LValue) {
        match lv {
            LValue::Name(n) => self.push(n.clone()),
            LValue::Index { table, key } => {
                self.emit_prefix_expr(table);
                self.push("[");
                self.emit_expr(key);
                self.push("]");
            }
            LValue::Field { table, field } => {
                self.emit_prefix_expr(table);
                self.push(".");
                self.push(field.clone());
            }
        }
    }

    fn emit_prefix_expr(&mut self, e: &Expr) {
        if Self::is_prefix_expr(e) {
            self.emit_expr(e);
        } else {
            self.push("(");
            self.emit_expr(e);
            self.push(")");
        }
    }

    fn emit_expr_list(&mut self, list: &[Expr]) {
        for (i, e) in list.iter().enumerate() {
            if i > 0 {
                self.push(",");
            }
            self.emit_expr(e);
        }
    }

    fn emit_expr(&mut self, e: &Expr) {
        match e {
            Expr::Nil => self.push("nil"),
            Expr::Bool(b) => self.push(if *b { "true" } else { "false" }),
            Expr::Number(n) => self.format_number(*n),
            Expr::String(bytes) => self.format_string_literal(bytes),
            Expr::Vararg => self.push("..."),
            Expr::Name(n) => self.push(n.clone()),
            Expr::Paren(inner) => {
                self.push("(");
                self.emit_expr(inner);
                self.push(")");
            }
            Expr::Table(fields) => {
                self.push("{");
                for (i, f) in fields.iter().enumerate() {
                    if i > 0 {
                        self.push(",");
                    }
                    match f {
                        TableField::Index { key, value } => {
                            self.push("[");
                            self.emit_expr(key);
                            self.push("]");
                            self.push("=");
                            self.emit_expr(value);
                        }
                        TableField::Name { field, value } => {
                            self.push(field.clone());
                            self.push("=");
                            self.emit_expr(value);
                        }
                        TableField::Array(value) => self.emit_expr(value),
                    }
                }
                self.push("}");
            }
            Expr::Function(f) => {
                self.push("function");
                self.emit_func_body(f);
            }
            Expr::IfExpr {
                branches,
                else_expr,
            } => {
                for (i, (c, v)) in branches.iter().enumerate() {
                    self.push(if i == 0 { "if" } else { "elseif" });
                    self.emit_expr(c);
                    self.push("then");
                    self.emit_expr(v);
                }
                self.push("else");
                self.emit_expr(else_expr);
            }
            Expr::InterpString { .. } => {
                unreachable!("generated VM runtime never uses backtick interpolated strings")
            }
            Expr::Index { table, key } => {
                self.emit_prefix_expr(table);
                self.push("[");
                self.emit_expr(key);
                self.push("]");
            }
            Expr::Field { table, field } => {
                self.emit_prefix_expr(table);
                self.push(".");
                self.push(field.clone());
            }
            Expr::Call { func, args } => {
                self.emit_prefix_expr(func);
                self.push("(");
                self.emit_expr_list(args);
                self.push(")");
            }
            Expr::MethodCall {
                receiver,
                method,
                args,
            } => {
                self.emit_prefix_expr(receiver);
                self.push(":");
                self.push(method.clone());
                self.push("(");
                self.emit_expr_list(args);
                self.push(")");
            }
            Expr::Unary { op, expr } => {
                let u = match op {
                    UnOp::Neg => "-",
                    UnOp::Not => "not",
                    UnOp::Len => "#",
                };
                self.push(u);
                let child_p = Self::expr_prec(expr);
                // Note: `^` (prec 8) binds tighter than unary `-` (`-2^2 == -(2^2)`), which is >= 7!
                if child_p < 7 {
                    self.push("(");
                    self.emit_expr(expr);
                    self.push(")");
                } else {
                    self.emit_expr(expr);
                }
            }
            Expr::Binary { lhs, op, rhs } => {
                let (prec, right_assoc) = Self::bin_prec(*op);
                let lp = Self::expr_prec(lhs);
                let rp = Self::expr_prec(rhs);

                let wrap_lhs = if matches!(op, BinOp::Lt | BinOp::Gt | BinOp::Le | BinOp::Ge | BinOp::Ne | BinOp::Eq) {
                    lp <= prec
                } else if right_assoc {
                    lp <= prec
                } else {
                    lp < prec
                };

                // In Lua/Luau, `^` allows unary operators on its RHS (`2 ^ -3`), so RHS of `^`
                // only needs parens when `rp < 7`!
                let wrap_rhs = if *op == BinOp::Pow {
                    rp < 7
                } else if right_assoc {
                    rp < prec
                } else {
                    rp <= prec
                };

                if wrap_lhs {
                    self.push("(");
                    self.emit_expr(lhs);
                    self.push(")");
                } else {
                    self.emit_expr(lhs);
                }

                let bop = match op {
                    BinOp::Add => "+",
                    BinOp::Sub => "-",
                    BinOp::Mul => "*",
                    BinOp::Div => "/",
                    BinOp::FloorDiv => "//",
                    BinOp::Mod => "%",
                    BinOp::Pow => "^",
                    BinOp::Concat => "..",
                    BinOp::Eq => "==",
                    BinOp::Ne => "~=",
                    BinOp::Lt => "<",
                    BinOp::Le => "<=",
                    BinOp::Gt => ">",
                    BinOp::Ge => ">=",
                    BinOp::And => "and",
                    BinOp::Or => "or",
                };
                self.push(bop);

                if wrap_rhs {
                    self.push("(");
                    self.emit_expr(rhs);
                    self.push(")");
                } else {
                    self.emit_expr(rhs);
                }
            }
        }
    }
}

fn is_ident_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn needs_space(prev: &[u8], curr: &[u8]) -> bool {
    if prev.is_empty() || curr.is_empty() {
        return false;
    }
    let pl = *prev.last().unwrap();
    let cf = curr[0];

    if is_ident_char(pl) && is_ident_char(cf) {
        return true;
    }
    if (prev[0].is_ascii_digit() && cf == b'.') || (pl == b'.' && cf.is_ascii_digit()) {
        return true;
    }
    if pl == b'-' && cf == b'-' {
        return true;
    }
    if pl == b'.' && cf == b'.' {
        return true;
    }
    if matches!(pl, b'<' | b'>' | b'~' | b'=') && cf == b'=' {
        return true;
    }
    if pl == b'/' && cf == b'/' {
        return true;
    }
    if pl == b':' && cf == b':' {
        return true;
    }
    if pl == b'[' && (cf == b'[' || cf == b'=') {
        return true;
    }
    false
}

/// Parses generated Luau source, performs scope-aware 1–2 char binding renaming with
/// sibling reuse and ancestor capture reservation, audits zero private leaks, and
/// renders the Moonveil single-line release output (`0x` / `0b` / decimal) beneath `RELEASE_HEADER`.
pub fn minify_lua_single_line(src: &str, rng: &mut Prng) -> String {
    minify_lua_single_line_with_names(src, rng, None)
}

/// As [`minify_lua_single_line`], but optionally draws all renamed local and member
/// identifiers from a user-supplied seed word list instead of the default short-name scheme.
pub fn minify_lua_single_line_with_names(
    src: &str,
    rng: &mut Prng,
    names: Option<&[String]>,
) -> String {
    let mut ast = parse_luau(src).expect("generated VM Luau must parse cleanly");
    let globals = collect_unbound_globals(&ast);

    let candidates = build_candidates(names, rng);
    // Any assigned name longer than 2 chars (seed-word mode) is legitimate; the auditor
    // uses this to distinguish deliberate long names from leaked original identifiers.
    let allowed_long: HashSet<String> = candidates
        .iter()
        .filter(|c| c.len() > 2)
        .cloned()
        .collect();

    let mut renamer = ScopeRenamer {
        candidates: candidates.clone(),
        globals: globals.clone(),
        env: Vec::new(),
    };
    renamer.rename_root(&mut ast);

    let mut member_renamer = MemberRenamer::new(candidates, rng);
    member_renamer.rename_block(&mut ast);

    audit_release_ast(&ast, &globals, &allowed_long);

    let mut emitter = MoonveilEmitter {
        tokens: Vec::with_capacity(src.len() / 3),
        rng,
    };
    emitter.emit_block(&ast);

    let mut out = String::with_capacity(RELEASE_HEADER.len() + 2 + src.len());
    out.push_str(RELEASE_HEADER);
    out.push('\n');

    for idx in 0..emitter.tokens.len() {
        if idx > 0
            && needs_space(
                emitter.tokens[idx - 1].as_bytes(),
                emitter.tokens[idx].as_bytes(),
            )
        {
            out.push(' ');
        }
        out.push_str(&emitter.tokens[idx]);
    }
    out.push('\n');
    out
}
